-- Migration 0003: Rebuild traffic_violations_catalog with correct violation IDs
-- Drops cttu_code from catalog, uses sequential serial PK (1..N).
-- Updates traffic_violations.violation_id and description via description matching.

-- Step 1: Drop FK from traffic_violations to old catalog
ALTER TABLE traffic_violations DROP CONSTRAINT IF EXISTS traffic_violations_violation_id_traffic_violations_catalog_id_fk;

-- Step 2: Drop old catalog table
DROP TABLE IF EXISTS traffic_violations_catalog CASCADE;

-- Step 3: Create new catalog without cttu_code, using serial PK
CREATE TABLE traffic_violations_catalog (
    id SERIAL PRIMARY KEY,
    law_code TEXT NOT NULL,
    canonical_description TEXT NOT NULL,
    known_variants TEXT[] NOT NULL DEFAULT '{}',
    category TEXT NOT NULL,
    differentiation TEXT,
    created_at TIMESTAMPTZ DEFAULT now() NOT NULL
);

CREATE INDEX idx_tvc_category ON traffic_violations_catalog (category);
CREATE INDEX idx_tvc_variants ON traffic_violations_catalog USING gin (known_variants);

-- Step 4: Insert catalog data (order matches CSV; serial ID auto-assigned)







-- Step 5: Reset all violation_ids (old catalog IDs are incompatible with new catalog)
UPDATE traffic_violations SET violation_id = NULL;

-- Step 6: Update traffic_violations.violation_id and description
-- Match by exact description = canonical_description or description IN known_variants
-- When multiple matches exist, prefer exact canonical_description match, then lowest catalog id
UPDATE traffic_violations tv SET
    violation_id = best.catalog_id,
    description = best.canonical_description
FROM (
    SELECT DISTINCT ON (tv2.id)
        tv2.id as violation_row_id,
        tvc.id as catalog_id,
        tvc.canonical_description
    FROM traffic_violations tv2
    JOIN traffic_violations_catalog tvc
        ON tv2.description = tvc.canonical_description
        OR tv2.description = ANY(tvc.known_variants)
    ORDER BY
        tv2.id,
        CASE WHEN tv2.description = tvc.canonical_description THEN 0 ELSE 1 END,
        tvc.id
) best
WHERE tv.id = best.violation_row_id;

-- Step 7: Re-add FK constraint
ALTER TABLE traffic_violations
    ADD CONSTRAINT traffic_violations_violation_id_traffic_violations_catalog_id_fk
    FOREIGN KEY (violation_id) REFERENCES traffic_violations_catalog(id);
